WITH base AS (SELECT * FROM departments WHERE location <> 'Singapore' AND location IN ('New York', 'Bangkok')), departments_stats AS (SELECT CASE WHEN budget >= 3168000 THEN 'high' WHEN budget >= 1436000 THEN 'mid' ELSE 'low' END AS budget_bucket, AVG(budget) AS avg_budget, MAX(budget) AS max_budget FROM base GROUP BY CASE WHEN budget >= 3168000 THEN 'high' WHEN budget >= 1436000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, avg_budget, max_budget FROM departments_stats WHERE avg_budget < 2419000 ORDER BY 2, budget_bucket;
